<template>
  <FormField
    v-slot="slots"
    :validate-on-model-update="effectiveLiveValidate"
    :validate-on-change="effectiveLiveValidate"
    :validate-on-blur="effectiveLiveValidate"
    :name="name"
  >
    <FormItem :class="itemClass">
      <FormControl>
        <div :class="cn('flex flex-col gap-2', row && 'flex-row items-center', slotWrapperClass)">
          <Label
            v-if="label"
            :for="name"
            :class="cn('flex flex-row text-nowrap', description && 'items-center gap-1', labelClass)"
            ><span>{{ label }}</span> <span v-if="isRequired" class="text-destructive">*</span>
            <Popover v-if="description">
              <PopoverTrigger type="button"><CircleQuestionMarkIcon class="w-5 h-5" /></PopoverTrigger>
              <PopoverContent side="top" class="text-wrap max-w-72 w-fit p-4 z-40">
                <p class="font-semibold mb-4">{{ label }}</p>
                {{ description }}
              </PopoverContent>
            </Popover>
          </Label>
          <slot v-bind="{ slots }" />
        </div>
        <FormMessage v-if="!isNoMessage" />
      </FormControl>
    </FormItem>
  </FormField>
</template>

<script setup lang="ts">
import { cn } from '@/lib/utils';
import { CircleQuestionMarkIcon } from 'lucide-vue-next';
import type { Ref } from 'vue';
import { inject } from 'vue';

interface Props {
  placeholder?: string;
  label?: string;
  name: string;
  isRequired?: boolean;
  isNoMessage?: boolean;
  row?: boolean;
  itemClass?: string;
  /**
   * When true, vee-validate's FormField re-validates on model-update / change / blur.
   * If unset, falls back to an injected `liveValidate` ref from an ancestor, otherwise false.
   */
  liveValidate?: boolean;
  slotWrapperClass?: string;
  /** Optional help text; renders a click-Popover (?) next to the label. */
  description?: string;
  /** Extra classes for the label, e.g. `text-wrap` to allow long labels to wrap in narrow grid cells. */
  labelClass?: string;
}

const props = withDefaults(defineProps<Props>(), {
  liveValidate: undefined,
  placeholder: undefined,
  label: undefined,
  itemClass: undefined,
  slotWrapperClass: undefined,
});
const injectedLive = inject<Ref<boolean> | undefined>('liveValidate', undefined);
const effectiveLiveValidate = computed(() => props.liveValidate ?? injectedLive?.value ?? false);
</script>
